import{z as o,x as n,o as B,c as s,q as l,j as e,D as a,d as i,s as r,S as t}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"拓扑感知的并行","description":"","frontmatter":{"title":"拓扑感知的并行","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/dist-topology-aware.md","filePath":"llm/dist-topology-aware.md","lastUpdated":1791063341000}'),p={name:"llm/dist-topology-aware.md"};function d(D,E,P,m,C,h){const A=n("Mermaid");return B(),s("div",null,[E[2]||(E[2]=l('<h1 id="拓扑感知的并行" tabindex="-1">拓扑感知的并行 <a class="header-anchor" href="#拓扑感知的并行" aria-label="Permalink to &quot;拓扑感知的并行&quot;">​</a></h1><div class="epigraph"><p>逻辑网格写在进程组里，物理网格写在交换机里；两个网格对不上，带宽表全部作废。</p><footer>—— 据 DGX SuperPOD 一类参考架构与 Jiang 等 2024 整理</footer></div><p><a href="/llm/dist-comm-overlap">上一课</a>把通信排进时间线；这些交换能不能按计划走完，取决于它们落在哪条物理链路。主干课的 <a href="/llm/rail-optimized-topology">rail-optimized 拓扑</a>给了 rail 的定义，<a href="/llm/topology-aware-placement">拓扑感知放置</a>给了放置的验收口径；本课深钻映射本身：进程组到链路的映射为什么是个约束满足问题、三类典型错法、以及映射的验证。不重讲 Clos 结构。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>同一份并行配置，映射不同，利用率可以差出两位数百分比。映射的本质是把「通信最密的组」放进「最密的子图」，同时不让任何一条链路的聚合流量超过它的物理上限。它难在约束互相咬：TP 要 NVLink 域、PP 想要跨节点均匀摊、EP 的 All-to-All 压根没有可聚合结构、DP 又想把尽量多的卡拉进同一个归约组。三类高频错法：把 TP 组绑到跨轨（配置写了 NVLink 域，启动脚本把 rank 顺序排错）；多个作业共享同一 rail 平面（各自的带宽模型都按独占算，跑起来互相拖）；EP 的 All-to-All 铺满跨节点（置换流量把轨的假设打穿）。</p><p><span class="marginnote">两个词先翻译：「NVLink 域」是一台机器里八张卡之间的高速直连网，出不了机箱；「rail（轨）」可以想成每个机柜竖着一排专用电梯——同号卡的流量各坐各的电梯上行，互不挤占。</span></p>',6)),(B(),e(t,null,{default:a(()=>[r(A,{id:"mermaid-16",class:"mermaid",graph:"flowchart%20LR%0A%20%20subgraph%20RD%5B%22DP%20%E5%BD%92%E7%BA%A6%E8%B5%B0%20rail%3A%20%E9%A1%BA%E7%9D%80%E6%8B%93%E6%89%91%22%5D%0A%20%20%20%20R1%5B%22%E5%90%8C%E5%8F%B7%20GPU%20%E5%AF%B9%E9%BD%90%E5%90%8C%E4%B8%80%E4%B8%8A%E8%A1%8C%E5%B9%B3%E9%9D%A2%22%5D%20--%3E%20R2%5B%22%E8%8A%82%E7%82%B9%E5%86%85%E5%85%88%E5%BD%92%E7%BA%A6%2C%20%E8%B7%A8%E6%AE%B5%E6%AF%8F%E8%8A%82%E7%82%B9%E4%B8%80%E4%BB%BD%E4%BD%93%E7%A7%AF%22%5D%20--%3E%20R3%5B%22%E6%9C%80%E5%A4%9A%E4%B8%A4%E8%B7%B3%2C%20%E5%90%84%E7%BB%84%E6%B5%81%E9%87%8F%E4%B8%8D%E6%B7%B7%E9%93%BE%E8%B7%AF%22%5D%0A%20%20end%0A%20%20subgraph%20EPX%5B%22EP%20%E7%9A%84%20All-to-All%3A%20%E9%80%86%E7%9D%80%E6%8B%93%E6%89%91%22%5D%0A%20%20%20%20E1%5B%22N%20%E4%BB%BD%E6%B5%81%E9%87%8F%E5%90%84%E5%8E%BB%E4%B8%8D%E5%90%8C%E7%9B%AE%E7%9A%84%E5%9C%B0%22%5D%20--%3E%20E2%5B%22%E7%BD%AE%E6%8D%A2%E6%97%A0%E8%81%9A%E5%90%88%E7%82%B9%2C%20%E8%BD%A8%E7%9A%84%E5%90%8C%E5%8F%B7%E5%81%87%E8%AE%BE%E8%A2%AB%E5%87%BB%E7%A9%BF%22%5D%20--%3E%20E3%5B%22%E8%A6%81%E4%B9%88%E6%95%B4%E7%BB%84%E8%BF%9B%20NVLink%20%E5%9F%9F%2C%20%E8%A6%81%E4%B9%88%E6%8E%A5%E5%8F%97%E8%B7%A8%E6%AE%B5%E9%99%8D%E9%80%9F%22%5D%0A%20%20end%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[i(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=l('<h3 id="映射的次序" tabindex="-1">映射的次序 <a class="header-anchor" href="#映射的次序" aria-label="Permalink to &quot;映射的次序&quot;">​</a></h3><p>映射按通信密度从高到低装填。第一层，NVLink 域：TP 组整组落在单机八卡内，开了 CP 的头维组同样处理。第二层，机柜内轨：PP 的相邻阶段优先同轨相邻节点，让点对点只走一跳。第三层，跨轨平面：DP 组沿轨展开，让 rail-optimized 的同号对齐结构服务梯度归约；层次化的节点内先归约、节点间再归约，跨段只走每节点一份的体积。第四层，EP 单独算账：换头方案把 All-to-All 压进 NVLink 域，代价是头数要能整除；Ring 方案沿轨走跨节点，代价是时延。绑定、NUMA 与 GPU Direct 是映射的一部分：绑核错一档，等于没做 rail 优化。</p><p><span class="marginnote">初学者容易以为「配置写了 TP 度为 8，通信库就会自动找对那八张卡」；实际库只保证「走对链路」，rank 排列是用户侧的事——启动脚本把 rank 顺序排错，TP 组照样被绑到跨轨，带宽表全部作废。</span></p><p><span class="marginnote">映射验证的一条硬规则：启动后用与真实消息大小相同的微基准跑一遍环测，把 busbw 和物理上限对照；再用一次「故意错绑」的对照跑，确认错绑确实变慢——变慢不了，说明你的测量没接住映射，MFU 差异另有原因。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把映射写成流量矩阵上的问题：每类进程组给出一组「谁和谁、每步多少字节」的边，链路给容量，目标是存在一种 rank 到设备的排列，使每条链路的利用率都不超过一。精确求解不现实也不必要，工程上按次序贪心装填再校验：装填完算最忙链路的利用率，它决定 step 的尾；利用率接近一的链路是下一步优化的靶子。多租户场景把「共享的轨」标成降容链路，带宽模型按共享比例打折——独占假设在共享平面上的误差不是小量。</p><p><span class="marginnote">「最忙链路决定 step 尾」像晚高峰的主干道：全城平均车速再好看，堵死的那条路照样把所有人的到达时间拉齐——归约是全组合同，最慢的那条边按住全组等它。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>rail 为什么对归约友好：同号 GPU 对齐到同一上行平面，DP 组内任意成员间最多两跳，且每条上行链路只承载自己这一组的流量；层次化归约把这个性质用满。All-to-All 为什么打穿 rail：置换没有中间聚合点，\\(N\\) 份流量各自去不同的目的地，轨的「同号对齐」帮不上忙，所以 EP 的放置要么整组进 NVLink 域，要么接受跨段降速。最忙链路决定 step 尾的机制与落后者同构：归约是全组合同，最慢的那条边把全组按住，平均利用率救不了尾。</p>',9)),(B(),e(t,null,{default:a(()=>[r(A,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20GROUPS%5B%22%E8%BF%9B%E7%A8%8B%E7%BB%84%E4%B8%8E%E6%AF%8F%E6%AD%A5%E6%B5%81%E9%87%8F%E7%9F%A9%E9%98%B5%22%5D%20--%3E%20L1%5B%22%E7%AC%AC%E4%B8%80%E5%B1%82%3A%20NVLink%20%E5%9F%9F%E8%A3%85%20TP%20%E4%B8%8E%20CP%20%E5%A4%B4%E7%BB%B4%22%5D%0A%20%20L1%20--%3E%20L2%5B%22%E7%AC%AC%E4%BA%8C%E5%B1%82%3A%20%E6%9C%BA%E6%9F%9C%E5%86%85%E8%BD%A8%E8%A3%85%20PP%20%E7%9B%B8%E9%82%BB%E9%98%B6%E6%AE%B5%22%5D%0A%20%20L2%20--%3E%20L3%5B%22%E7%AC%AC%E4%B8%89%E5%B1%82%3A%20%E8%B7%A8%E8%BD%A8%E5%B9%B3%E9%9D%A2%E8%A3%85%20DP%20%E5%BD%92%E7%BA%A6%22%5D%0A%20%20L3%20--%3E%20L4%5B%22%E7%AC%AC%E5%9B%9B%E5%B1%82%3A%20EP%20%E5%8D%95%E7%8B%AC%E5%AE%9A%E5%9F%9F%E6%88%96%E9%99%8D%E9%80%9F%22%5D%0A%20%20L4%20--%3E%20CHECK%5B%22%E7%8E%AF%E6%B5%8B%E5%AF%B9%E7%85%A7%20%2B%20%E9%94%99%E7%BB%91%E5%AF%B9%E7%85%A7%20%2B%20%E6%9C%80%E5%BF%99%E9%93%BE%E8%B7%AF%E5%88%A9%E7%94%A8%E7%8E%87%22%5D%0A%20%20CHECK%20--%3E%7C%E4%B8%8D%E8%BF%87%7C%20REMAP%5B%22%E6%94%B9%20rank%20%E6%8E%92%E5%88%97%E9%87%8D%E8%A3%85%E5%A1%AB%22%5D%0A%20%20CHECK%20--%3E%7C%E8%BF%87%7C%20RUN%5B%22%E5%9B%BA%E5%AE%9A%E6%98%A0%E5%B0%84%E8%BF%9B%E8%AE%AD%E7%BB%83%E9%85%8D%E7%BD%AE%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[i(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=l('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>Clos 与轨的物理定义见 <a href="/llm/rail-optimized-topology">rail-optimized 拓扑</a>及其前一课；NCCL 如何自行发现拓扑见<a href="/llm/pretrain-comm">上一课</a>——注意库的发现只保证「走对链路」，不保证「排对 rank」，排 rank 是用户侧映射的责任。云上同型号实例不保证同拓扑，跨实例迁移后映射要重验。弹性事件后世界大小变了，映射作废、按新网格重放，这根线接到后课的容错链路。映射不是一次性的配置，是随拓扑与并行配置联动的资产。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>映射是约束满足：最密的组进最密的子图，任何链路利用率不超过一。</li><li>装填次序：NVLink 域收 TP 与 CP 头维，机柜内轨收 PP，跨轨平面收 DP，EP 单独定域。</li><li>All-to-All 是置换，打穿 rail 假设；EP 要么进 NVLink 域，要么接受跨段降速。</li><li>最忙链路决定 step 尾；共享平面按比例降容，不信独占假设。</li><li>验证靠环测加错绑对照；映射随拓扑、配置与弹性事件重放。</li><li>出处：DGX SuperPOD 一类 rail-optimized 参考架构；Jiang 等，MegaScale，2024 的放置实践。</li></ul>',4))])}const c=o(p,[["render",d]]);export{F as __pageData,c as default};
